add('2.1',['另外存一排參數，才讓訓練能改「這個字提供哪些數字」，又不改編碼約定。','這裡只是說明數字如何影響預測，沒有用這個假設證明訓練已成功。'],'五列新ID映射明示、lookup[1,2,1]->[1,3,3]重复貓同向量；额外共有配方正确地連到候选分數而非假實測。',[('中間embedding','ID索引可调V×D参数表，再经输出配方；本例D3不同候选数5。','保持ID定位固定而让字提供的線索可调，供多个字共同預测。'),('共享候選配方','狗分數=2feature1+feature3，貓2/看0；貓feature1->1.5使分数3。','字表与後续配方可分别改变候选分數，梯度回傳實際使用列；仅机制示意。')],['1.1','1.6','1.10','1.12','first-steps'])
add('2.2',['數字沒有相加，順序沒有丟掉。','三字與五字長卡無法直接交給同一個固定輸入大小的配方。'],'拼接保留三位置及order，reshape(2,-1)到[2,6]正确，不互混batch；固定context成本约定明示。',[('按位置拼接/reshape','[B,C,D]->[B,C×D]保持每笔原顺序；反向词序得不同長卡。','讓多个字共同送後续配方且各位置乘數可不同，保留order；需要固定C才尺寸吻合。')],['2.1','first-steps'])
add('2.3',['Linear 只沿最後一個特徵軸計算。','方形表即使寫錯，也可能不報錯而算出另一套配方。'],'Linear存[2,3]配方、bias与10/2正確；手动@转置一致；位置独立与先拼接才能混前文界線清楚。',[('線性配方/transpose/bias','x[1,3]@W.T[3,2]+bias->10/2，改一權重增4。','拼接只是保存，需加权让多个格共同影响新特征；各笔仍分開。')],['2.2','first-steps'])
add('2.4',['單一加權公式 `y=k*x+b` 是一直線，無法同時透過這三點。','本節手動填配方，只展示「算得出什麼」。'],'相同两Linear对照无ReLU=0/加入=absx，展示非线性改变斜率；合法模型表示性不变成训练成功宣称。',[('兩套Linear合成','bWa權重0 ->三样本全0；一般加權/偏移仍合成仿射。','多接Linear不能完成独立目标离零多遠的三点规则。'),('ReLU非线性','先[x,-x]，负清0后sum ->2/0/2，多段不同斜率。','用可见转折补直线表示限制；保持同weights控制是哪個机制改变。')],['2.3','first-steps'])
add('2.5',['相同輸入只能得到相同候選分配','視窗變長時參數也增加，驗證只有一篇，這份結果不能證明所有任務三字最好。'],'手工颜色/形状答案假設明示，五字才可区分；MLP raw counts833/1345/1857和三组post-update NLL一致；公平比較與1验证篇限制已教。',[('可見窗口','近1是/近3物體是/近4色物體是同，两题近5始分红蓝，8字练习同理。','沒有关键颜色输入无法条件分辨两题；可见只是学会机会。'),('拼接成本','H×C×D weights，C增影响一侧，MLPtotal833->1345->1857。','多線索有成本，主張只用于固定其他部分的配方计数。'),('MLP非线性与实测比較','embedding+flatten+hidden+tanh+output 与 frozenContextMLP一致；200steps同9/1documents。','可见增多不保证留出好；三字后五字train更低valid更高，不能选成普遍最优。')],['1.12','1.14','2.1','2.2','2.3','2.4'],[{'focus':'三模型原始比較設定','status':'raw_values_and_data_hash_verified','evidence':'technical-foundations-evidence/simple_models-raw.json#/results/runs','selectors':['mlp1','mlp3','mlp5'],'denominator':'9 train docs103targets,1validationdoc11targets；after_nll_same_post_update_time字段；seed42,width16,200steps；参数随C变化','data_evidence':'technical-foundations-evidence/local-raw-artifact-checks.json','interpretation':'same cases/budget, different parameter count; descriptive observation not isolated causal evidence'}],['未重跑200steps；原權重實際重評測未做，局部資料與manifesthash已核'])
add('chapter-03',['分清「提出需求、匹配位置、取回內容」三個角色'],'固定视窗可用线索后引入内容读法，Q/K/V基本角色预告合理；不把不同读法当天然语意。',[('注意力阶段预告','先比例混合，后内容匹配，因果许可與多头。','導覽／參考，詳細機制合理待教')],['2.5'])
add('3.1',['比例較大也不直接代表帶回數值較大。','本例兩張都有參與。'],'非负sum1加权混合得[1.8,.4]及反读[.2,3.6]正确，沒有把大权重当贡献/理解或可无损还原。',[('加權平均讀取','weights@[sourcepositions,features]给一张同宽output；两卡各乘自己比例。','想多用第一卡时.9/.1改变读法并保特征宽度；不等于拼接保每卡。')],['2.2','2.3','first-steps'])
add('3.2',['候選位置沒有改，偏好已因需求改變；這就是用內容決定讀法。','它不是只量方向的相似度'],'q/key点积取正负matching再沿候选softmax；q换维导致第二候选最多，向量大小影响分数限定准确。',[('q/key/dot score/比例','q[1,0]dotKs->[1,0,-1] ->.665/.245/.090，q[0,1]使第二最多。','让比例随目前需求而改，source卡不动；手工机制不主张学习成功。')],['1.7','3.1','first-steps'])
add('3.3',['query 表示提出需求，key 表示提供匹配線索','查詢數與候選數不必相等，但兩邊的匹配特徵數要相同。'],'Q/K区别来自role与独立配方，非文法标签；矩形Q[2,2]K.T[2,3]给[2,3]正确，行问题/列candidate与自注意来源界線清楚。',[('獨立query/key投影','同源X可各经不同Linear，示意保留/交换[1,2]为不同表示；QK.T不改变角色。','一个位置要提出需求也要供他位匹配，两工作允许独立配方而不用绑同数；不主张同配方不能完成所有任务。'),('多query矩形score','每query一行，候选一欄，Dk相同才dot；查询和候选数量可不同。','一次给每问者自己的全candidate分数；softmax行内分配不能互抢比例。')],['2.3','3.1','3.2'])
add('3.4',['左比例乘左 V，右比例乘右 V','本節仍用未縮放的透明算例；完整縮放規則在下一節。'],'matching2维/values3维和source行顺序正确；[7.0416,14.0833,21.1249]数值一致；QKV来自sameX讲明但示意直接填不同query/candidate数，不混成已训练self-attention。',[('K/V角色与对应','K提供定位数，V实际带回内容，weights[1,2]@V[2,3]->output[1,3]。','书目和内容可不同宽，匹配定位后需取相应source内容；调V不调K所以比例不变。'),('QKV全路與來源','sameX独立三个Linear可训；例无实际projection，仅softmax(QK.T)V。','分开需求、匹配和带回，避免把matching向量宽度当output宽度；缩放合理待下一节。')],['2.3','3.1','3.2','3.3'])
add('3.5',['對 D 個獨立、平均為 0、變異數為 1 的格子，加總變異數為 D，標準差為 √D。','除以 √D 不保證分數永遠同樣大。'],'独立±1乘积条件明确，sumvarianceD/sqrtD推導正确；1000sample短检标准差接近2/8再缩1，非训练/普遍不變性證明。',[('点积缩放','Rademacher q/k products var1独立，sumstd√D；scores/√D控制dimension起伏。','只增特征数不希望无意使softmax大幅集中；减弱这种尺度变化，不能抵消q/k全部变化。')],['1.7','1.15','3.2','3.3','3.4'])
add('3.6',['位置 i 只准讀位置 j≤i','若只是把分數設成普通 0，softmax 仍會給它機會，不能排除。'],'tril True许可、-inf屏蔽、B/H/T/D轴与均匀前缀读回一致；未来卡+100前三output无变assert实跑通过。',[('因果mask与query/key坐标','allowed[1,1,4,4]行query列key，i读j<=i；遮后score=-inf使exp0。','完整训练材料已有答案但生成没有，挡未来避免拿答案猜答案；自身当前允许因目标是右邻。'),('未来扰动实际检查','均匀allowed各行1,1/2,1/3,1/4；改Vposition3只可影响query3。','不仅看三角图，要看未来改动是否改变过去out；与shift任务配对分别核。')],['1.3','1.7','3.4','3.5'])
add('3.7',['兩頭都讀整串允許的位置','K 的最後軸是特徵，不是讀取比例表的候選位置'],'各头完整前文/独立特征与输出拼接正确；指定手算不同於实际随机輸入，cache[1,2,4,4]和改4头[1,4,4,2]静态符合。',[('multi-head/QKV split','total8 split2×4，先[1,4,2,4]transpose[1,2,4,4]，每头四位置，各拼8经outLinear。','同位置可能需几种读法；自由度允许多个matching/内容配方，不预设语意或声称更准。'),('cache输出','保存K/V与out共同返回；K最后特征dim4而非候选数。','以后逐字重用旧K/V基本角色已给，本页仅shape检查，无需提前缓存完整算法。')],['2.2','2.3','3.3','3.4','3.5','3.6'])
add('chapter-04',['核對輸入、答案與求導，再談增加層數會改變什麼。'],'把position/attention/per-position transform/output路线组完整的任务预告合理；Dense是本章配置，不提前宣称语言能力。',[('整體Transformer预告','重复同宽block并候选打分，后核任务到gradient。','導覽／參考，詳細機制合理待教')],['2.1','3.7'])
add('4.1',['同一個字放不同位置','加入位置使線索可用，後面的計算還要學會使用它，不代表相加後已懂語序。'],'absolute learnable position table三格逐加與same字不同向量正确；capacity5只索引0..4、causal约定与position用途有別。',[('位置表与逐格加','e(ID)+p(index)同宽，貓position0[1,0,0]/2[1.2,.4,.6]不同。','ID仅字同就同起始向量，额外position数字让位置可见；没有已用好语序或超长度泛化宣称。')],['2.1','3.6'])
add('4.2',['不讓原表示必須整份透過新分支','它不保證訓練永不失敗，也不表示所有原文能完整還原'],'residualx+f(x)same-shape、direct与branch同源、各路derivative相加机制准确；sum只测试敏感度未当文字loss。',[('殘差直接路','x[1,2]+2x ->[3,6]；sum反传each3，zero分支仍信息x、gradient1。','在已有表示加修正同时留直通信息/梯度，来源中让不全靠新branch的需要明确。')],['1.10','1.11','3.4'])
add('4.3',['不是沿兩個位置一起算','LN 是先整理再可調，最終不必永遠零平均。'],'LN最后轴population variance/epsilon/gamma/beta正確，整体平移allclose/单格修改差异对位；跨位置误标准化会泄漏的界线有效。',[('per-position LN','每position自mean/var，[1,2,3]与10倍各近[-1.225,0,1.225]，samepos全部+100近不变。','后续配方前抑制任意尺度；各位置独立才能保因果前文边界。'),('epsilon与affine params','sqrt(v+eps)防零除；每feature共享gamma,beta，设2/1后mean1var近4。','相同格输入需数值可算，保留后续可调尺度而不是永久mean0假保证。')],['3.5','3.6','first-steps'])
add('4.4',['擴張的是特徵，不是文字位置；縮回則讓結果能加到四格的殘差主路。','共享配方不等於位置互相讀取'],'DenseFFN4->16->4和GELU匹配frozen implementation；per-position相同输入给同输出，Dense完整配方与跨位置attention分工不混。',[('FFN扩张/GELU/缩回','up[16,4],down[4,16]，非线性夹中间，最后返回same4features。','attention读回后需卡内特征组合；扩张给中间表示再收回同宽可残差，16是当前示例设置而非最优性论证。'),('Dense共享位置配方','相同two-position input用同weights给相同values；Linear/GELU无位置混合。','区别各卡内部加工和跨卡交流，Dense不用按字选一部分FFN。')],['2.3','2.4','3.7','4.2'])
add('4.5',['主路沒有被 LN 永久替換；LN 在分支中。','不是答案 loss 為 0'],'pre-norm两段x+AttentionLN/u+FFNLN与Block.forward一致；out与cache与aux各分清，auxDense0不是零答案代价。',[('pre-norm block/两残差','保主x/u，branchLN先整理再attention/FFN后相加；sameB/T/D。','沿前文残差保已有表示，同时分支处理尺度；希望可反复同宽接下一层。没有承诺证明胜过post-norm。'),('返回状态/auxiliary','y,cache,auxiliary三项，Denseaux初始化scalar0，不用答案。','代码检查连线/shape时不把aux0误当语言任务loss0或学习完成。')],['3.7','4.2','4.3','4.4'])
add('4.6',['續寫只先用最後那排選新 ID，再把它接回輸入重算','本次初始化的平均代價約 3.336。'],'LM head每position8->20候选、末LN与logits字典、next-target flatten顺序正确；初始化实跑3.335639匹配3.336，不代表训练。',[('输出层/hidden/logits轴','TinyLM最后LN+LinearbiasFalse；[1,3,20]每position20候选，argmax-1->[1,3]。','内部8features不是候选分数；需每候选自己的配方，并与attention head术语区分。'),('生成取最后与loss整题flatten','续写只拿最后候选行；三题CE把logits[1,3,20]->[3,20],targets[1,3]->[3]保持对应2/3/4。','生成增一字而训练可已知三答案一次评分；不把所有position预测一次串起。')],['1.7','1.8','1.14','4.1','4.5'])
add('4.7',['它不會再幫你 shift。','模型尚未學會這段序列'],'shifted与masked_loss接口唯一shift一致；完整序列任务、因果input范围与三题loss/gradient给定，代码没有step；原实测causal0对raw字段。',[('完整序列对齐/损失','[1,2,3,4]x前三/y后三；scores[1,3,5]flatten后sameposition target；masked_loss仅ignore+mean。','三道next-ID题可同时评分但不读未来；重shift/复制会改任务，必须先对题。'),('backward无update','loss.backward累参数grad，本页无step或手改。','核数据->模型->代价->梯度通路，不误称训练成功。'),('额外实测防偷看','text_foundation结果causal_max_difference0，probe最后13->14，比较前三以前四位置全部候选。','需要检查未来输入不改变过去logits，loss下降不能代答；与当前短cells不同层证据。')],['1.3','1.10','1.13','3.6','4.6'],[{'focus':'原始causal_max_difference','status':'raw_field_supported','evidence':'technical-foundations-evidence/text_foundation-raw.json#/results/causal_max_difference','version':'b52935d99f58b694cd932ac158c10c4d8d92d4c2; cuda/seed42/PyTorch2.14.1+cu126','scope':'仅引用的未来扰动最大差0.0；data9/1/2与training141568/600steps metadata核对；其他scaling/resume结果不审','implementation':'frozen scripts/course_experiments/text.py run_text_foundation probe；model.py/attention.py静态逻辑与小cells实跑','boundary':'原始runner SHA不同于currentfreeze；不宣称这个baseline重新产生原CUDA结果'}],['原始CUDA训练及历史runner完整重放未做；原artifact远端与整个训练datasetmanifest未重新下载'])
add('4.8',['總數為 `1360+深度×840`。','沒有另做同預算一層對照，不能用來證明兩層更好。'],'1/2/3层2200/3040/3880実数符合独立block840+shared入口出口1360，明细attention无bias/FFN有bias正确；额外raw141568配置计数成立而非效果比較。',[('depth/独立block','第2层读第1更新表示而非每次原x；各block840，入口出口1360共存一份。','更多层增新的组合与运算/存储，不保持对所有量同一倍率；本页仅结构计数。'),('参数计数与宽度成本','W8时QKV/out4×64=256，FFN512+40，LN32；W64trained42112+2×49728=141568。','数清多层代价，并限制更多参数非更准证明；需要真正同预算留出比较才评质量。')],['2.1','2.3','3.7','4.3','4.4','4.5','4.6'],[{'focus':'额外trained模型配置数字','status':'raw_and_static_count_verified','evidence':['technical-foundations-evidence/text_foundation-raw.json#/results/training/parameters','technical-foundations-evidence/simple-checkpoint-evaluation.json#/text_foundation_config_count'],'scope':'vocab264,width64,layers2,max_length128 static count141568；不重跑训练、不读scaling实验成果'}])
